    q=sorted((s[i],e[i]) for i in range(n)); day=0; ans=0; i=0; h=[]
    import heapq
    while i<n or h:
      if not h: day=max(day,q[i][0])
      while i<n and q[i][0]<=day: heapq.heappush(h,q[i][1]); i+=1
      while h and h[0]<day: heapq.heappop(h)
      if h: heapq.heappop(h); ans+=1; day+=1
    return str(ans)

